package ai.finsight.goal;

import ai.finsight.transaction.*;import ai.finsight.user.UserRepository;
import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
import java.math.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;

@Service @Transactional
public class FinancialGoalService {
 public record Input(@NotBlank @Size(max=120) String name,@NotBlank @Size(max=40) String category,@NotNull @DecimalMin("0.01") @Digits(integer=17,fraction=2) BigDecimal targetAmount,@NotNull @DecimalMin("0.00") @Digits(integer=17,fraction=2) BigDecimal currentAmount,@NotNull LocalDate targetDate,@NotNull FinancialGoal.Priority priority,@Size(max=1000) String description){}
 public record View(UUID id,String name,String category,BigDecimal targetAmount,BigDecimal currentAmount,LocalDate targetDate,FinancialGoal.Priority priority,String description,BigDecimal progressPercentage,BigDecimal remainingAmount,BigDecimal requiredMonthlySavings,BigDecimal assumedMonthlySavings,LocalDate projectedCompletionDate,String status){}
 private final FinancialGoalRepository goals;private final UserRepository users;private final TransactionRepository transactions;
 public FinancialGoalService(FinancialGoalRepository g,UserRepository u,TransactionRepository t){goals=g;users=u;transactions=t;}
 @Transactional(readOnly=true) public List<View> list(String email){UUID owner=owner(email);BigDecimal assumption=monthlySavingsAssumption(owner);return goals.findAllByUserIdOrderByTargetDateAsc(owner).stream().map(g->view(g,assumption)).toList();}
 public View create(String email,Input in){UUID owner=owner(email);return view(goals.save(new FinancialGoal(owner,in.name().trim(),in.category().trim(),in.targetAmount(),in.currentAmount(),in.targetDate(),in.priority(),in.description())),monthlySavingsAssumption(owner));}
 public View update(String email,UUID id,Input in){UUID owner=owner(email);FinancialGoal g=goals.findByIdAndUserId(id,owner).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));g.update(in.name().trim(),in.category().trim(),in.targetAmount(),in.currentAmount(),in.targetDate(),in.priority(),in.description());return view(goals.save(g),monthlySavingsAssumption(owner));}
 public void delete(String email,UUID id){UUID owner=owner(email);goals.delete(goals.findByIdAndUserId(id,owner).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND)));}
 private View view(FinancialGoal g,BigDecimal assumed){BigDecimal target=g.getTargetAmount(),current=g.getCurrentAmount(),remaining=target.subtract(current).max(BigDecimal.ZERO).setScale(2,RoundingMode.HALF_UP);BigDecimal progress=current.multiply(BigDecimal.valueOf(100)).divide(target,2,RoundingMode.HALF_UP).min(BigDecimal.valueOf(100));long months=Math.max(1,ChronoUnit.MONTHS.between(YearMonth.now(),YearMonth.from(g.getTargetDate())));BigDecimal required=remaining.divide(BigDecimal.valueOf(months),2,RoundingMode.HALF_UP);LocalDate projected=null;String status="AT_RISK";if(remaining.signum()==0){projected=LocalDate.now();status="COMPLETED";}else if(assumed.signum()>0){long needed=remaining.divide(assumed,0,RoundingMode.CEILING).longValue();projected=LocalDate.now().plusMonths(Math.max(1,needed));status=projected.isAfter(g.getTargetDate())?"AT_RISK":"ON_TRACK";}return new View(g.getId(),g.getName(),g.getCategory(),target,current,g.getTargetDate(),g.getPriority(),g.getDescription(),progress,remaining,required,assumed,projected,status);}
 private BigDecimal monthlySavingsAssumption(UUID owner){YearMonth current=YearMonth.now();BigDecimal total=BigDecimal.ZERO;for(int i=3;i>=1;i--){YearMonth month=current.minusMonths(i);LocalDate from=month.atDay(1),to=month.plusMonths(1).atDay(1);BigDecimal income=transactions.sumForOwnerAndPeriod(owner,from,to,FinancialTransaction.Direction.INCOME);BigDecimal expenses=transactions.sumForOwnerAndPeriod(owner,from,to,FinancialTransaction.Direction.EXPENSE);total=total.add(income.subtract(expenses));}return total.divide(BigDecimal.valueOf(3),2,RoundingMode.HALF_UP);}
 private UUID owner(String email){return users.findByEmailIgnoreCase(email).orElseThrow().getId();}
}
